import java.util.*;

class Solution {
  public long minimumCost(int[] nums) {
    Arrays.sort(nums);
    String text = Long.toString(nums[nums.length / 2]);
    int half = (text.length() + 1) / 2;
    long prefix = Long.parseLong(text.substring(0, half));
    ArrayList<Long> candidates = new ArrayList<>();
    for (long p : new long[] {prefix - 1, prefix, prefix + 1}) {
      if (p <= 0) continue;
      String first = Long.toString(p);
      String tail = new StringBuilder(first.substring(0, text.length() / 2)).reverse().toString();
      candidates.add(Long.parseLong(first + tail));
    }
    candidates.add((long) Math.pow(10, text.length() - 1) - 1);
    candidates.add((long) Math.pow(10, text.length()) + 1);
    long answer = Long.MAX_VALUE;
    for (long palindrome : candidates) {
      long cost = 0;
      for (int value : nums) cost += Math.abs((long) value - palindrome);
      answer = Math.min(answer, cost);
    }
    return answer;
  }
}
